<?php
namespace Ishep\Repositories;use PDO;use Ishep\Services\DocumentStatus;
final class MemberDocumentRepository
{public function __construct(private PDO $db){}private function base():string{return'SELECT d.*,dt.code document_type_code,dt.name document_type_name,u.name,u.email,a.application_number,mt.id membership_type_id,mt.name membership_type_name,v.name verifier_name FROM member_documents d JOIN document_types dt ON dt.id=d.document_type_id JOIN users u ON u.id=d.user_id JOIN membership_applications a ON a.id=d.membership_application_id JOIN membership_types mt ON mt.id=a.membership_type_id LEFT JOIN users v ON v.id=d.verified_by ';}public function types(int $membershipType):array{$s=$this->db->prepare('SELECT dt.id,dt.code,dt.name,dt.description,COALESCE(r.required,0) required FROM document_types dt LEFT JOIN membership_document_requirements r ON r.document_type_id=dt.id AND r.membership_type_id=? AND r.active=1 WHERE dt.active=1 ORDER BY COALESCE(r.required,0) DESC,dt.name');$s->execute([$membershipType]);return$s->fetchAll();}public function type(int $id):?array{$s=$this->db->prepare('SELECT * FROM document_types WHERE id=? AND active=1');$s->execute([$id]);return$s->fetch()?:null;}public function currentForApplication(int $app):array{$s=$this->db->prepare($this->base()."WHERE d.membership_application_id=? AND d.verification_status NOT IN ('replaced','removed') ORDER BY d.uploaded_at DESC");$s->execute([$app]);return$s->fetchAll();}public function byReference(string $ref):?array{$s=$this->db->prepare($this->base().'WHERE d.document_reference=? LIMIT 1');$s->execute([$ref]);return$s->fetch()?:null;}public function insert(array $d):int{$s=$this->db->prepare("INSERT INTO member_documents(document_reference,user_id,membership_application_id,document_type_id,original_filename,storage_key,relative_path,detected_mime,extension,byte_size,sha256,verification_status,uploaded_at,created_at,updated_at) VALUES (?,?,?,?,?,?,?,?,?,?,?,'pending',UTC_TIMESTAMP(),UTC_TIMESTAMP(),UTC_TIMESTAMP())");$s->execute([$d['reference'],$d['user_id'],$d['application_id'],$d['type_id'],$d['original'],$d['storage_key'],$d['relative_path'],$d['mime'],$d['extension'],$d['size'],$d['sha256']]);return(int)$this->db->lastInsertId();}public function transition(int $id,string $to,int $actor,?string $reason=null,?string $internal=null,?int $replacement=null):void{$sql='UPDATE member_documents SET verification_status=?,updated_at=UTC_TIMESTAMP()';$v=[$to];if(in_array($to,['verified','rejected'],true)){$sql.=',verified_by=?,verified_at=UTC_TIMESTAMP(),rejection_reason=?,internal_note=?';array_push($v,$actor,$reason,$internal);}if($to==='replaced'){$sql.=',replaced_document_id=?';$v[]=$replacement;}$sql.=' WHERE id=?';$v[]=$id;$this->db->prepare($sql)->execute($v);}public function event(int $id,?int $actor,string $event,?string $from,string $to,?string $note):void{$this->db->prepare('INSERT INTO member_document_events(member_document_id,actor_user_id,event_type,previous_status,new_status,note,created_at) VALUES(?,?,?,?,?,?,UTC_TIMESTAMP())')->execute([$id,$actor,$event,$from,$to,$note]);}public function events(int $id,bool $staff=false):array{$s=$this->db->prepare('SELECT e.*,u.name actor_name FROM member_document_events e LEFT JOIN users u ON u.id=e.actor_user_id WHERE e.member_document_id=? ORDER BY e.id');$s->execute([$id]);$r=$s->fetchAll();if(!$staff)foreach($r as &$x)if($x['event_type']==='verified')$x['note']=null;return$r;}public function queue(?string $status,string $search,int $type,int $membership,int $limit=50):array{$w=[];$v=[];if($status&&in_array($status,DocumentStatus::ALL,true)){$w[]='d.verification_status=?';$v[]=$status;}if($type){$w[]='d.document_type_id=?';$v[]=$type;}if($membership){$w[]='mt.id=?';$v[]=$membership;}if($search!==''){$w[]='(d.document_reference LIKE ? OR a.application_number LIKE ? OR u.name LIKE ? OR u.email LIKE ?)';$term='%'.$search.'%';array_push($v,$term,$term,$term,$term);}$s=$this->db->prepare($this->base().($w?'WHERE '.implode(' AND ',$w).' ':'').'ORDER BY d.uploaded_at DESC LIMIT '.max(1,min(100,$limit)));$s->execute($v);return$s->fetchAll();}public function counts(?int $user=null):array{$out=array_fill_keys(['pending','verified','rejected'],0);$sql="SELECT verification_status,COUNT(*) total FROM member_documents WHERE verification_status IN ('pending','verified','rejected')";$v=[];if($user){$sql.=' AND user_id=?';$v[]=$user;}$sql.=' GROUP BY verification_status';$s=$this->db->prepare($sql);$s->execute($v);foreach($s->fetchAll()as$r)$out[$r['verification_status']]=(int)$r['total'];return$out;}}
